"""
Pure-Python prebuild script: generates version.c with build timestamp.

Called from the framework build scripts to embed build metadata.
Cross-platform — no .exe dependencies.
"""

import os
import time


def generate_version_source(output_path):
    """Generate a version.c file with the current build timestamp."""
    timestamp = time.strftime("%b %d %Y %H:%M:%S", time.localtime())

    content = """\
/* Auto-generated by buildtime.py — do not edit */
const char build_date[] = "%s";
""" % timestamp

    # Only write if content changed (avoids unnecessary recompilation)
    if os.path.isfile(output_path):
        with open(output_path, "r") as f:
            if f.read() == content:
                return

    output_dir = os.path.dirname(output_path)
    if output_dir and not os.path.isdir(output_dir):
        os.makedirs(output_dir)

    with open(output_path, "w") as f:
        f.write(content)
